"""app.py - Child safety companion (Streamlit)."""import jsonimport osimport refrom pathlib import Pathfrom google import genaifrom google.genai import typesimport streamlit as stfrom rules import CONCERNING_TAGS, HIGH_TAGS, LEVEL_NAMES, assessst.set_page_config(page_title="Safe Space", page_icon="💛", layout="centered")TAGGER_MODEL = "gemini-3.5-flash-lite"REPLY_MODEL = "gemini-3.5-flash-lite"KNOWN_TAGS = HIGH_TAGS | CONCERNING_TAGSBASE_DIR = Path(__file__).parent# ---------- load prompts ----------def load_prompt(name):    path = BASE_DIR / name    if not path.exists():        st.error(f"Missing file: {name}. Put it next to app.py.")        st.stop()    return path.read_text(encoding="utf-8")SAFETY_GUIDE = load_prompt("safety_guide.md")TAGGER_PROMPT = load_prompt("tagger_prompt.md")# ---------- text and labels ----------MODE_LABELS = {    "victim": "VICTIM (the child or teen themselves)",    "sibling": "SIBLING / FRIEND (someone who noticed something)",    "parent": "PARENT (a parent who found out or is worried)",}MODES = [    ("victim", "I need help", "Something feels off in a chat or with someone older."),    ("sibling", "I'm worried about someone", "A sibling or friend may be in a bad situation."),    ("parent", "I'm a parent", "I found something or I'm worried about my child."),]GREETINGS = {    "victim": "Hi, I'm glad you're here. You can tell me what's going on, "              "or paste a chat, at your own pace. Nobody is going to judge you. "              "What's on your mind?",    "sibling": "Hi. It's kind of you to notice and want to help. "               "Tell me what you saw or what they told you, and we'll "               "work out a safe next step together.",    "parent": "Hi. It's good that you're looking into this. Tell me what you "              "found or what's worrying you, and we'll go through it calmly.",}PLACEHOLDERS = {    "victim": "Type what happened, or paste the chat...",    "sibling": "Tell me what you saw or what they told you...",    "parent": "Tell me what you found or what worries you...",}BANNERS = {    "victim": "This looks serious, and it is not your fault. You don't have to handle it alone.",    "sibling": "This looks serious. Stay calm, keep the evidence, and support them. "               "A trusted adult or the police should know.",    "parent": "This looks serious. Your child was manipulated and is not at fault. "              "Calm support and the police are the next step.",}AGE_Q = {    "victim": "How much older is the other person than you?",    "sibling": "How much older is the other person than the child?",    "parent": "How much older is the other person than your child?",}AGE_OPTIONS = {    "Same age, or under 5 years older": 0,    "5 or more years older": 5,    "Not sure": 0,}LEVEL_UI = {    "LOW": ("#2e7d32", "#e8f5e9", "Nothing worrying so far"),    "CONCERNING": ("#b26a00", "#fff4e0", "Some warning signs"),    "HIGH": ("#b71c1c", "#fdecea", "This needs attention now"),}LEVEL_GUIDE = {    "LOW": "Be warm and curious. Don't alarm anyone. Ask a gentle question if needed. "           "Keep it brief.",    "CONCERNING": "Kindly name the pattern you see (it can be a warning sign) and explain "                  "briefly why it matters. Give 2–3 clear next steps. Be thorough enough "                  "to actually help, but don't pad.",    "HIGH": "Be calm and direct. Say it is not their fault. Give clear, concrete next steps "            "and explain briefly why each matters. Include the help list where it fits. "            "Be thorough — don't cut off early. Don't pad with filler.",}TAG_LABELS = {    "secrecy": "Asked to keep it secret",    "secrecy_from_parents": "Asked to hide it from family",    "topic_return": "Brought back something already refused",    "guilt_pressure": "Made them feel guilty for saying no",    "personal_questions": "Personal or love-life questions",    "platform_shift": "Moved to a more private app",    "isolation": "Pulled them away from others",    "age_comment": "Comments about their age",    "photo_probe": "Hinted at wanting pictures",    "gifts_or_money": "Gifts or money offered",    "sexual_joke_probe": "Sexual jokes or comments",    "fake_peer_identity": "Identity that may not be real",    "romantic_framing": "Called it a special bond or relationship",    "blame_shame_child": "Blamed or shamed the child",    "supervision_probe": "Asked who checks the phone",    "photo_request": "Asked for photos or video",    "meet_request": "Asked to meet",    "threat": "Threats",    "blackmail": "Blackmail",    "money_demand": "Asked for money",    "sexual_content_sent": "Sent sexual material",    "pressure_after_sent": "Kept pushing after a photo was sent",    "child_fear": "Feeling scared",    "child_sees_relationship": "Sees it as a relationship",}RESCUE_Q1 = {    "Share it with friends, school or family": "share",    "Demand money": "money",    "Demand more pictures or other things": "more",    "I'm not sure what they'll do": "unsure",}RESCUE_Q2 = {    "I never sent an intimate picture": "never_sent",    "I sent a picture": "sent",    "I'm not sure / don't want to say": "prefer_not",}FALLBACK_REPLY = (    "I'm having trouble replying right now, and I'm sorry. Please try sending "    "your message again.\n\nIf you are in danger or being threatened, call **112**. "    "**Childline 1098** is free and open 24x7.")HELP_MD = """- **Childline 1098**: free, 24x7, for any child who needs help. Anyone can call for a child.- **Police 112**: if there is a threat, blackmail, someone wants to meet, or you feel unsafe.- **Cyber Crime Helpline 1930**: online blackmail, threats, fake profiles.- **cybercrime.gov.in**: report cybercrime online.- **A trusted adult**: older sibling, aunt or uncle, school counselor, teacher."""CSS = """<style>.block-container {max-width: 820px; padding-top: 2.2rem;}.hero {text-align: center; padding: 0.5rem 0 1.2rem 0;}.hero h1 {font-size: 2.3rem; margin-bottom: 0.2rem;}.hero p {font-size: 1.05rem; opacity: 0.85; max-width: 560px; margin: 0 auto;}.badge {padding: 0.55rem 0.8rem; border-radius: 10px; font-weight: 600;        text-align: center; margin-bottom: 0.6rem;}.banner {padding: 0.8rem 1rem; border-radius: 10px; margin-bottom: 1rem;         background: #fdecea; color: #7f1111; border: 1px solid #b71c1c;}.note {font-size: 0.85rem; opacity: 0.75;}</style>"""st.markdown(CSS, unsafe_allow_html=True)# ---------- state ----------def init_state():    defaults = {        "mode": None, "started": False, "messages": [], "api_messages": [],        "tag_history": [], "seen_tags": set(), "level": "LOW",        "age_gap": 0, "authority": False, "rescue_mode": False,    }    for key, value in defaults.items():        if key not in st.session_state:            st.session_state[key] = valuedef reset():    st.session_state.clear()    st.rerun()# ---------- LLM ----------def get_api_key():    key = os.environ.get("GEMINI_API_KEY")    if key:        return key    try:        return st.secrets["GEMINI_API_KEY"]    except Exception:        return None@st.cache_resourcedef get_client(api_key):    return genai.Client(api_key=api_key)SAFETY = [    types.SafetySetting(category=c, threshold="BLOCK_ONLY_HIGH")    for c in ("HARM_CATEGORY_SEXUALLY_EXPLICIT", "HARM_CATEGORY_HARASSMENT",              "HARM_CATEGORY_HATE_SPEECH", "HARM_CATEGORY_DANGEROUS_CONTENT")]def call_llm(system, messages, model, max_tokens):    contents = [        types.Content(            role="model" if m["role"] == "assistant" else "user",            parts=[types.Part(text=m["content"])],        )        for m in messages    ]    resp = get_client(get_api_key()).models.generate_content(        model=model,        contents=contents,        config=types.GenerateContentConfig(            system_instruction=system,            max_output_tokens=max_tokens,            temperature=0.7,            safety_settings=SAFETY,            thinking_config=types.ThinkingConfig(thinking_level="medium"),        ),    )    return (resp.text or "").strip()def parse_tags(raw):    empty = {"tags": [], "after_refusal": False}    match = re.search(r"\{.*\}", raw or "", re.S)    if not match:        return empty    try:        data = json.loads(match.group(0))    except json.JSONDecodeError:        return empty    if not isinstance(data, dict):        return empty    raw_tags = data.get("tags", [])    if not isinstance(raw_tags, list):        raw_tags = []    tags = [t for t in raw_tags if isinstance(t, str) and t in KNOWN_TAGS]    return {"tags": tags, "after_refusal": bool(data.get("after_refusal", False))}def recent_context(n=4):    users = [m["content"][:600] for m in st.session_state.messages if m["role"] == "user"]    return "\n".join(f"User: {t}" for t in users[-n:])def tag_message(text):    content = (        f"CONTEXT (earlier messages from the user):\n{recent_context() or '(none)'}\n\n"        "NOTE: the NEW MESSAGE below was typed by the person using the app. It may be "        "their own words, a pasted chat with Him/Her lines, or a description of what "        "another person did. Tag the behaviors it shows or describes.\n\n"        f"NEW MESSAGE:\n{text}"    )    try:        raw = call_llm(TAGGER_PROMPT, [{"role": "user", "content": content}], TAGGER_MODEL, 1000)        return parse_tags(raw)    except Exception:        return {"tags": [], "after_refusal": False}def generate_reply():    s = st.session_state    tags = ", ".join(sorted(s.seen_tags)) or "none"    runtime = (        "\n\nRUNTIME CONTEXT (set by the app, not by the user)\n"        f"- Mode: {MODE_LABELS[s.mode]}\n"        f"- Risk level: {s.level}\n"        f"- Warning signs detected so far: {tags}\n"        f"- Tone for this level: {LEVEL_GUIDE[s.level]}\n"        "- Reply in the language the user writes in (English or Hinglish). "    )    reply = call_llm(SAFETY_GUIDE + runtime, s.api_messages, REPLY_MODEL, 2084)    if not reply:        raise ValueError("empty reply")    return replydef process(prompt):    s = st.session_state    prompt = prompt.strip()[:4000]    tagged = tag_message(prompt)    s.tag_history.append(tagged)    s.seen_tags |= set(tagged["tags"])    s.level = LEVEL_NAMES[assess(s.tag_history, s.age_gap, s.authority)]    if s.mode == "victim" and (        "blackmail" in tagged["tags"]        or "threat" in tagged["tags"]        or "money_demand" in tagged["tags"]	or "sexual_content_sent" in tagged["tags"]	or "photo_request" in tagged["tags"]    ):        s.rescue_mode = True        s.messages.append({"role": "user", "content": prompt})        return    s.api_messages.append({"role": "user", "content": prompt})    try:        reply = generate_reply()    except Exception:        reply = FALLBACK_REPLY    s.api_messages.append({"role": "assistant", "content": reply})    s.messages.append({"role": "user", "content": prompt})    s.messages.append({"role": "assistant", "content": reply})# ---------- screens ----------def show_welcome():    st.markdown(        '<div class="hero"><h1>Safe Space 💛</h1>'        "<p>A calm place to figure out if a chat or a person feels unsafe, "        "and what you can do about it. You're not in trouble here.</p></div>",        unsafe_allow_html=True,    )    st.markdown("#### Who is this for?")    cols = st.columns(3)    for col, (key, title, desc) in zip(cols, MODES):        with col:            with st.container(border=True):                st.markdown(f"**{title}**")                st.caption(desc)                if st.button("Choose", key=f"mode_{key}", use_container_width=True):                    st.session_state.mode = key                    st.rerun()    st.markdown(        "<p class='note'>I'm an AI, not a replacement for a trusted person. "        "This app doesn't store your chat. Your messages are sent to an AI service "        "to write replies.</p>",        unsafe_allow_html=True,    )def show_setup():    s = st.session_state    st.markdown("### Two quick questions")    st.caption("These help me understand the situation. You can pick 'Not sure'.")    with st.form("setup_form"):        age_choice = st.radio(AGE_Q[s.mode], list(AGE_OPTIONS.keys()), index=0)        authority = st.checkbox("The person is a teacher, coach, tutor, or someone in charge.")        submitted = st.form_submit_button("Start chatting", use_container_width=True)    if submitted:        s.age_gap = AGE_OPTIONS[age_choice]        s.authority = authority        s.messages = [{"role": "assistant", "content": GREETINGS[s.mode]}]        s.started = True        st.rerun()    if st.button("Back"):        s.mode = None        st.rerun()def show_sidebar():    s = st.session_state    color, bg, label = LEVEL_UI[s.level]    with st.sidebar:        st.markdown("### Safety check")        st.markdown(            f'<div class="badge" style="background:{bg};color:{color};'            f'border:1px solid {color}">{label}</div>',            unsafe_allow_html=True,        )        st.markdown("**Things worth noticing**")        if s.seen_tags:            for tag in sorted(s.seen_tags, key=lambda t: (t not in HIGH_TAGS, t)):                st.markdown(f"- {TAG_LABELS.get(tag, tag)}")        else:            st.caption("Nothing so far.")        with st.expander("Need help now?", expanded=(s.level == "HIGH")):            st.markdown(HELP_MD)        st.divider()        st.caption(f"Mode: {MODE_LABELS[s.mode].split(' (')[0].title()}")        if st.button("Start over", use_container_width=True):            reset()def show_chat():    s = st.session_state    show_sidebar()    if s.level == "HIGH":        st.markdown(f'<div class="banner">{BANNERS[s.mode]}</div>', unsafe_allow_html=True)    for m in s.messages:        with st.chat_message(m["role"]):            st.markdown(m["content"])    prompt = st.chat_input(PLACEHOLDERS[s.mode])    if prompt and prompt.strip():        with st.chat_message("user"):            st.markdown(prompt.strip()[:4000])        with st.chat_message("assistant"):            with st.spinner("Reading carefully..."):                process(prompt)        st.rerun()    st.caption("I'm an AI, not a replacement for a trusted person. "               "If you're in danger, call 112.")def show_rescue_flow():    s = st.session_state    show_sidebar()    st.markdown("## Blackmail rescue")    st.markdown(        "Someone is threatening you with an intimate image. "        "**You don't need to prove anything to get help.** "        "You don't need to show the image to anyone, and you don't need to say "        "whether you sent one. We'll work out the next steps together."    )    st.info(        "Don't send money or more pictures. Don't forward the image to anyone "        "or upload it here. Save the threatening messages and the account details."    )    with st.form("rescue_form"):        q1 = st.radio("What is the person threatening to do?", list(RESCUE_Q1.keys()))        q2 = st.radio("Which best describes the image?", list(RESCUE_Q2.keys()))        submitted = st.form_submit_button("Show my next steps", use_container_width=True)    if submitted:        st.session_state["rescue_q1"] = RESCUE_Q1[q1]        st.session_state["rescue_q2"] = RESCUE_Q2[q2]        st.session_state["rescue_shown"] = True    if st.session_state.get("rescue_shown"):        st.divider()        st.markdown("### Your next steps")        st.markdown(            "- **Keep the evidence.** Screenshot the messages, the account handle, "            "the profile link, and any demands. Don't delete anything.\n"            "- **Don't pay and don't send more.** Paying or sending more rarely stops "            "the threats, and it makes things harder later.\n"            "- **Don't forward the image.** Not to friends, not to family, not to us."        )        st.markdown("**Report and get help:**")        st.markdown(            "- **Cyber Crime Helpline 1930** — call for online blackmail and threats.\n"            "- **cybercrime.gov.in** — file a report online.\n"            "- **Childline 1098** — free, 24x7, for anyone under 18.\n"            "- **A trusted adult** — a parent, older sibling, aunt, uncle, or school counselor, "            "if you have someone you feel safe telling."        )        st.markdown(            "If the image is real and you want it taken down from participating platforms, "            "**Take It Down** (takeitdown.ncmec.org) can help. This is optional — it is not "            "required to get help."        )        st.success(            "**This is not your fault.** The person threatening you is committing a crime. "            "You don't have to handle this alone."        )        if st.button("Back to chat", use_container_width=True):            st.session_state["rescue_mode"] = False            st.rerun()# ---------- main ----------init_state()if not get_api_key():    st.error("No API key found. Set GEMINI_API_KEY (environment variable or "             ".streamlit/secrets.toml) and restart.")    st.stop()if st.session_state.mode is None:    show_welcome()elif not st.session_state.started:    show_setup()elif st.session_state.rescue_mode:    show_rescue_flow()else:    show_chat()